/// Keeps track of whether we are currently visiting a class or function definition in a
/// [`LogicalLine`]. If we are visiting a class or function, the enum also keeps track
/// of the [type parameters] of the class/function.
///
/// Call [`DefinitionState::visit_token_kind`] on the [`TokenKind`] of each
/// successive [`LogicalLineToken`] to ensure the state remains up to date.
///
/// [type parameters]: https://docs.python.org/3/reference/compound_stmts.html#type-params
#[derive(Debug, Clone, Copy)]
enum DefinitionState {
    InClass(TypeParamsState),
    InFunction(TypeParamsState),
    InTypeAlias(TypeParamsState),
    NotInDefinition,
}

impl DefinitionState {
    fn from_tokens<'a>(tokens: impl IntoIterator<Item = &'a LogicalLineToken>) -> Self {
        let mut token_kinds = tokens.into_iter().map(LogicalLineToken::kind);
        while let Some(token_kind) = token_kinds.next() {
            let state = match token_kind {
                TokenKind::Indent | TokenKind::Dedent => continue,
                TokenKind::Class => Self::InClass(TypeParamsState::default()),
                TokenKind::Def => Self::InFunction(TypeParamsState::default()),
                TokenKind::Async if matches!(token_kinds.next(), Some(TokenKind::Def)) => {
                    Self::InFunction(TypeParamsState::default())
                }
                TokenKind::Type => Self::InTypeAlias(TypeParamsState::default()),
                _ => Self::NotInDefinition,
            };
            return state;
        }
        Self::NotInDefinition
    }

    const fn in_function_definition(self) -> bool {
        matches!(self, Self::InFunction(_))
    }

    const fn type_params_state(self) -> Option<TypeParamsState> {
        match self {
            Self::InClass(state) | Self::InFunction(state) | Self::InTypeAlias(state) => {
                Some(state)
            }
            Self::NotInDefinition => None,
        }
    }

    fn in_type_params(self) -> bool {
        matches!(
            self.type_params_state(),
            Some(TypeParamsState::InTypeParams { .. })
        )
    }

    fn visit_token_kind(&mut self, token_kind: TokenKind) {
        let type_params_state_mut = match self {
            Self::InClass(type_params_state)
            | Self::InFunction(type_params_state)
            | Self::InTypeAlias(type_params_state) => type_params_state,
            Self::NotInDefinition => return,
        };

        let before_type_params = type_params_state_mut.before_type_params();
        let in_type_params = matches!(type_params_state_mut, TypeParamsState::InTypeParams { .. });
        let type_params_ended = matches!(type_params_state_mut, TypeParamsState::TypeParamsEnded);
        let tracks_type_param_delimiters = matches!(
            token_kind,
            TokenKind::Lpar | TokenKind::Lsqb | TokenKind::Rsqb | TokenKind::Equal
        );

        if !tracks_type_param_delimiters {
            if is_non_logical_token(token_kind) {
                if token_kind.is_trivia() {
                    if token_kind.is_any_newline() {
                        if before_type_params {
                            return;
                        }
                        return;
                    }
                    if matches!(token_kind, TokenKind::Comment) {
                        if type_params_ended {
                            return;
                        }
                        return;
                    }
                }
                if matches!(
                    token_kind,
                    TokenKind::Newline | TokenKind::Indent | TokenKind::Dedent
                ) {
                    return;
                }
            }

            if token_kind.is_keyword() {
                if token_kind.is_soft_keyword() {
                    if matches!(
                        token_kind,
                        TokenKind::Type | TokenKind::Match | TokenKind::Case
                    ) {
                        if before_type_params {
                            return;
                        }
                        return;
                    }
                }
                if token_kind.is_non_soft_keyword() {
                    if matches!(
                        token_kind,
                        TokenKind::True
                            | TokenKind::False
                            | TokenKind::None
                            | TokenKind::Class
                            | TokenKind::Def
                            | TokenKind::Async
                            | TokenKind::Lambda
                            | TokenKind::And
                            | TokenKind::Or
                            | TokenKind::Not
                            | TokenKind::In
                            | TokenKind::Is
                            | TokenKind::If
                            | TokenKind::Elif
                            | TokenKind::Else
                            | TokenKind::For
                            | TokenKind::While
                            | TokenKind::Try
                            | TokenKind::Except
                            | TokenKind::Finally
                            | TokenKind::With
                            | TokenKind::As
                            | TokenKind::Import
                            | TokenKind::From
                            | TokenKind::Return
                            | TokenKind::Yield
                            | TokenKind::Raise
                            | TokenKind::Pass
                            | TokenKind::Break
                            | TokenKind::Continue
                            | TokenKind::Global
                            | TokenKind::Nonlocal
                            | TokenKind::Del
                            | TokenKind::Assert
                            | TokenKind::Await
                    ) {
                        if in_type_params {
                            return;
                        }
                        return;
                    }
                }
            }

            if token_kind.is_operator() {
                if token_kind.is_arithmetic() {
                    if token_kind.is_unary_arithmetic_operator() {
                        if matches!(token_kind, TokenKind::Plus | TokenKind::Minus) {
                            if before_type_params {
                                return;
                            }
                            return;
                        }
                    }
                }
                if token_kind.is_bitwise_or_shift() {
                    if matches!(
                        token_kind,
                        TokenKind::LeftShift
                            | TokenKind::RightShift
                            | TokenKind::Amper
                            | TokenKind::Vbar
                            | TokenKind::CircumFlex
                            | TokenKind::Tilde
                            | TokenKind::LeftShiftEqual
                            | TokenKind::RightShiftEqual
                            | TokenKind::AmperEqual
                            | TokenKind::VbarEqual
                            | TokenKind::CircumflexEqual
                    ) {
                        return;
                    }
                }
                if matches!(
                    token_kind,
                    TokenKind::DoubleStarEqual
                        | TokenKind::StarEqual
                        | TokenKind::SlashEqual
                        | TokenKind::DoubleSlashEqual
                        | TokenKind::PlusEqual
                        | TokenKind::MinusEqual
                        | TokenKind::NotEqual
                        | TokenKind::Less
                        | TokenKind::Greater
                        | TokenKind::PercentEqual
                        | TokenKind::EqEqual
                        | TokenKind::LessEqual
                        | TokenKind::GreaterEqual
                        | TokenKind::Rarrow
                        | TokenKind::ColonEqual
                        | TokenKind::Slash
                        | TokenKind::Percent
                        | TokenKind::Star
                        | TokenKind::DoubleStar
                        | TokenKind::DoubleSlash
                        | TokenKind::At
                        | TokenKind::AtEqual
                        | TokenKind::Dot
                        | TokenKind::Ellipsis
                        | TokenKind::Comma
                        | TokenKind::Colon
                        | TokenKind::Semi
                        | TokenKind::Rpar
                        | TokenKind::Lbrace
                        | TokenKind::Rbrace
                        | TokenKind::Question
                        | TokenKind::Exclamation
                ) {
                    return;
                }
            } else if matches!(
                token_kind,
                TokenKind::Name
                    | TokenKind::Int
                    | TokenKind::Float
                    | TokenKind::Complex
                    | TokenKind::String
                    | TokenKind::FStringStart
                    | TokenKind::FStringMiddle
                    | TokenKind::FStringEnd
                    | TokenKind::IpyEscapeCommand
                    | TokenKind::Unknown
                    | TokenKind::EndOfFile
            ) {
                if before_type_params {
                    return;
                }
                return;
            }
        }

        match token_kind {
            TokenKind::Lpar if type_params_state_mut.before_type_params() => {
                *type_params_state_mut = TypeParamsState::TypeParamsEnded;
            }
            TokenKind::Lsqb => match type_params_state_mut {
                TypeParamsState::TypeParamsEnded => {}
                TypeParamsState::BeforeTypeParams => {
                    *type_params_state_mut = TypeParamsState::InTypeParams {
                        inner_square_brackets: 0,
                    };
                }
                TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } => *inner_square_brackets += 1,
            },
            TokenKind::Rsqb => {
                if let TypeParamsState::InTypeParams {
                    inner_square_brackets,
                } = type_params_state_mut
                {
                    if *inner_square_brackets == 0 {
                        *type_params_state_mut = TypeParamsState::TypeParamsEnded;
                    } else {
                        *inner_square_brackets -= 1;
                    }
                }
            }
            _ => {}
        }
    }
}

#[derive(Debug, Clone, Copy, Default)]
enum TypeParamsState {
    #[default]
    BeforeTypeParams,
    InTypeParams {
        inner_square_brackets: u32,
    },
    TypeParamsEnded,
}

impl TypeParamsState {
    const fn before_type_params(self) -> bool {
        matches!(self, Self::BeforeTypeParams)
    }
}

